const pptxgen = require('pptxgenjs');
const fs = require('fs');
const path = require('path');

const pptx = new pptxgen();
pptx.layout = 'LAYOUT_16X9';
pptx.author = 'OpenAI';
pptx.company = 'OpenAI';
pptx.subject = 'Global renewable energy trends in 2025';
pptx.title = 'Global Renewable Energy in 2025: How Far Have We Come?';
pptx.lang = 'en-US';
pptx.theme = {
  headFontFace: 'Arial',
  bodyFontFace: 'Arial',
  lang: 'en-US'
};
pptx.defineLayout({ name: 'CUSTOM_16_9', width: 10, height: 5.625 });
pptx.layout = 'CUSTOM_16_9';
pptx.margin = 0;
pptx.layout = 'LAYOUT_16X9';
pptx.width = 10;
pptx.height = 5.625;
pptx.defineSlideMaster({
  title: 'BASE',
  background: { color: 'F7FAF7' },
  objects: [
    { line: { x: 0.38, y: 5.1, w: 8.8, h: 0, line: { color: 'D9E6DC', width: 0.6 } } },
  ],
  slideNumber: { x: 9.35, y: 5.1, color: '5A6B60', fontFace: 'Arial', fontSize: 8 },
});

const out = '/app/output/final_deck.pptx';
const ASSET = '/app/benchmark/assets';
const theme = {
  bg: 'F7FAF7',
  panel: 'FFFFFF',
  ink: '10231B',
  muted: '5B6B62',
  faint: 'E8EFEA',
  line: 'D7E3DA',
  green: '147A45',
  green2: '28A86B',
  green3: '83C99B',
  blue: '166A8F',
  gold: 'E7B94E',
  orange: 'D67A22',
  red: 'B84A3D',
  dark: '0E3B2E',
};

function slideBase() {
  const slide = pptx.addSlide('BASE');
  slide.background = { color: theme.bg };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: theme.green }, line: { color: theme.green, transparency: 100 } });
  return slide;
}

function addTitle(slide, title, subtitle) {
  slide.addText(title, {
    x: 0.42, y: 0.26, w: 8.75, h: 0.42,
    fontFace: 'Arial', fontSize: 21, bold: true, color: theme.ink,
    margin: 0, breakLine: false, fit: 'shrink'
  });
  if (subtitle) {
    slide.addText(subtitle, {
      x: 0.44, y: 0.75, w: 8.9, h: 0.22,
      fontFace: 'Arial', fontSize: 8.5, color: theme.muted,
      margin: 0, breakLine: false, fit: 'shrink'
    });
  }
}

function addSource(slide, text = 'Source: Our World in Data; Ember (2026); Energy Institute Statistical Review of World Energy (2025).') {
  slide.addText(text, { x: 0.42, y: 5.22, w: 7.25, h: 0.16, fontSize: 5.6, color: '708078', margin: 0, fit: 'shrink' });
}

function pill(slide, text, x, y, w, color = theme.green, fill = 'E9F6EE') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.28, rectRadius: 0.07, fill: { color: fill }, line: { color: fill, transparency: 100 } });
  slide.addText(text, { x: x + 0.1, y: y + 0.06, w: w - 0.2, h: 0.12, fontSize: 7.5, bold: true, color, align: 'center', margin: 0, fit: 'shrink' });
}

function statCard(slide, stat, label, x, y, w, h, color = theme.green, note = '') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.08, fill: { color: theme.panel }, line: { color: theme.line, width: 0.8 } });
  slide.addText(stat, { x: x + 0.18, y: y + 0.18, w: w - 0.36, h: 0.45, fontSize: 25, bold: true, color, margin: 0, fit: 'shrink' });
  slide.addText(label, { x: x + 0.18, y: y + 0.73, w: w - 0.36, h: 0.42, fontSize: 9.2, color: theme.ink, bold: true, margin: 0.02, fit: 'shrink' });
  if (note) slide.addText(note, { x: x + 0.18, y: y + h - 0.34, w: w - 0.36, h: 0.22, fontSize: 6.7, color: theme.muted, margin: 0, fit: 'shrink' });
}

function bulletList(slide, items, x, y, w, h, size = 9, color = theme.ink) {
  const runs = [];
  items.forEach((item, idx) => {
    runs.push({ text: item, options: { bullet: { type: 'ul' }, breakLine: idx < items.length - 1 } });
  });
  slide.addText(runs, { x, y, w, h, fontSize: size, color, margin: 0.02, breakLine: false, fit: 'shrink', paraSpaceAfterPt: 4, valign: 'top' });
}

function addImageContain(slide, image, x, y, w, h) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: 'FFFFFF' }, line: { color: theme.line, width: 0.8 } });
  slide.addImage({ path: path.join(ASSET, image), x: x + 0.06, y: y + 0.06, w: w - 0.12, h: h - 0.12, sizing: { type: 'contain', x: x + 0.06, y: y + 0.06, w: w - 0.12, h: h - 0.12 } });
}

function addProgressBar(slide, pct, x, y, w, h, color, bg = 'E6ECE8') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.04, fill: { color: bg }, line: { color: bg, transparency: 100 } });
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w: w * pct, h, rectRadius: 0.04, fill: { color }, line: { color, transparency: 100 } });
}

function addColumnChart(slide, data, x, y, w, h, maxVal, unit) {
  const barW = w / data.length * 0.48;
  const gap = w / data.length * 0.52;
  slide.addShape(pptx.ShapeType.line, { x, y: y + h, w, h: 0, line: { color: theme.line, width: 1 } });
  [0.25,0.5,0.75,1].forEach(fr => {
    slide.addShape(pptx.ShapeType.line, { x, y: y + h - h * fr, w, h: 0, line: { color: 'ECF2EE', width: 0.5 } });
  });
  data.forEach((d, i) => {
    const bx = x + i * (barW + gap) + gap * 0.28;
    const bh = h * (d.value / maxVal);
    slide.addShape(pptx.ShapeType.rect, { x: bx, y: y + h - bh, w: barW, h: bh, fill: { color: d.color }, line: { color: d.color, transparency: 100 } });
    slide.addText(d.value.toLocaleString(), { x: bx - 0.18, y: y + h - bh - 0.25, w: barW + 0.36, h: 0.16, fontSize: 7.5, bold: true, color: theme.ink, align: 'center', margin: 0 });
    slide.addText(d.label, { x: bx - 0.23, y: y + h + 0.12, w: barW + 0.46, h: 0.3, fontSize: 7.5, color: theme.muted, bold: true, align: 'center', margin: 0, fit: 'shrink' });
  });
  slide.addText(unit, { x: x, y: y - 0.24, w: 1.4, h: 0.16, fontSize: 6.8, color: theme.muted, margin: 0 });
}

function addSmallTable(slide, rows, x, y, w, h) {
  const headerH = 0.25;
  const rowH = (h - headerH) / rows.length;
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.04, fill: { color: 'FFFFFF' }, line: { color: theme.line, width: 0.8 } });
  slide.addShape(pptx.ShapeType.rect, { x, y, w, h: headerH, fill: { color: theme.dark }, line: { color: theme.dark, transparency: 100 } });
  slide.addText('Country / region', { x: x + 0.09, y: y + 0.07, w: w * 0.58, h: 0.1, fontSize: 6.2, bold: true, color: 'FFFFFF', margin: 0 });
  slide.addText('Renewable electricity', { x: x + w * 0.59, y: y + 0.07, w: w * 0.35, h: 0.1, fontSize: 6.2, bold: true, color: 'FFFFFF', align: 'right', margin: 0 });
  rows.forEach((r, i) => {
    const yy = y + headerH + rowH * i;
    if (i % 2 === 0) slide.addShape(pptx.ShapeType.rect, { x, y: yy, w, h: rowH, fill: { color: 'F4F8F5' }, line: { color: 'F4F8F5', transparency: 100 } });
    slide.addText(r[0], { x: x + 0.09, y: yy + rowH * 0.27, w: w * 0.55, h: 0.1, fontSize: 6.3, color: theme.ink, margin: 0, fit: 'shrink' });
    slide.addText(r[1], { x: x + w * 0.65, y: yy + rowH * 0.27, w: w * 0.29, h: 0.1, fontSize: 6.3, bold: true, color: r[2] || theme.green, align: 'right', margin: 0, fit: 'shrink' });
  });
}

function iconCircle(slide, x, y, text, label, color) {
  slide.addShape(pptx.ShapeType.ellipse, { x, y, w: 0.62, h: 0.62, fill: { color }, line: { color, transparency: 100 } });
  slide.addText(text, { x, y: y + 0.13, w: 0.62, h: 0.28, fontSize: 17, bold: true, color: 'FFFFFF', align: 'center', margin: 0, fit: 'shrink' });
  slide.addText(label, { x: x - 0.25, y: y + 0.78, w: 1.12, h: 0.28, fontSize: 7.1, color: theme.ink, bold: true, align: 'center', margin: 0, fit: 'shrink' });
}

// 1 Cover
{
  const slide = pptx.addSlide();
  slide.background = { color: theme.dark };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: 10, h: 5.625, fill: { color: theme.dark }, line: { color: theme.dark } });
  slide.addShape(pptx.ShapeType.arc, { x: 6.2, y: -0.55, w: 4.7, h: 4.7, adjustPoint: 0.25, line: { color: '2A9E62', transparency: 60, width: 2 }, fill: { color: theme.dark, transparency: 100 }, rotate: 10 });
  slide.addShape(pptx.ShapeType.arc, { x: 6.85, y: 0.15, w: 3.4, h: 3.4, adjustPoint: 0.25, line: { color: '80C995', transparency: 70, width: 1.2 }, fill: { color: theme.dark, transparency: 100 }, rotate: 18 });
  pill(slide, '2025 GLOBAL RENEWABLE ENERGY BRIEFING', 0.55, 0.62, 2.75, 'BFE9C9', '214E3A');
  slide.addText('Global Renewable\nEnergy in 2025:', { x: 0.55, y: 1.35, w: 5.8, h: 1.35, fontSize: 39, bold: true, color: 'FFFFFF', margin: 0, breakLine: false, fit: 'shrink' });
  slide.addText('How Far Have We Come?', { x: 0.55, y: 2.78, w: 6.5, h: 0.6, fontSize: 30, bold: true, color: 'A9E3B7', margin: 0, fit: 'shrink' });
  slide.addText('A data-driven overview of renewable energy across primary energy, electricity generation, technologies, and regions.', { x: 0.58, y: 3.62, w: 5.95, h: 0.45, fontSize: 12.2, color: 'DDEBE2', margin: 0, fit: 'shrink' });
  statCard(slide, '~14%', 'Global primary energy from renewables', 6.85, 3.1, 1.22, 1.18, theme.green2, '2024');
  statCard(slide, '~30%', 'Global electricity from renewables', 8.18, 3.1, 1.22, 1.18, theme.green2, '2025');
  slide.addText('Source: Our World in Data – Renewable Energy; Ember (2026); Energy Institute (2025).', { x: 0.58, y: 5.12, w: 7.0, h: 0.16, fontSize: 6.4, color: 'C5D8CD', margin: 0 });
}

// 2 Fossil urgency
{
  const slide = slideBase();
  addTitle(slide, '75% of Global GHG Emissions Still Come from Fossil Fuels', 'The renewable transition is also an air-quality and public-health imperative.');
  statCard(slide, '75%', 'Global greenhouse gas emissions from burning fossil fuels for energy', 0.55, 1.25, 2.55, 1.65, theme.red, 'Energy remains the central climate challenge.');
  statCard(slide, '5M+', 'Premature deaths each year from local air pollution linked to fossil combustion', 3.38, 1.25, 2.55, 1.65, theme.orange, 'Clean power reduces CO₂ and local pollutants.');
  statCard(slide, '2 levers', 'Scale low-carbon electricity while electrifying transport and heating', 6.2, 1.25, 2.55, 1.65, theme.green, 'Renewables and nuclear are the main low-carbon sources.');
  slide.addShape(pptx.ShapeType.roundRect, { x: 0.72, y: 3.45, w: 8.55, h: 1.05, rectRadius: 0.08, fill: { color: 'F1F7F3' }, line: { color: theme.line, width: 0.8 } });
  iconCircle(slide, 1.0, 3.65, 'CO₂', 'Climate forcing', theme.red);
  iconCircle(slide, 2.75, 3.65, '⚕', 'Health burden', theme.orange);
  iconCircle(slide, 4.5, 3.65, '⚡', 'Electricity gains', theme.blue);
  iconCircle(slide, 6.25, 3.65, '↗', 'Scale-up need', theme.green);
  slide.addText('Policy implication: the electricity sector is moving fastest, but total energy emissions will not fall fast enough unless transport and heating follow.', { x: 7.35, y: 3.67, w: 1.65, h: 0.58, fontSize: 7.6, color: theme.ink, bold: true, margin: 0.02, fit: 'shrink' });
  addSource(slide);
}

// 3 Primary energy
{
  const slide = slideBase();
  addTitle(slide, 'Renewables Now Supply ~14% of Global Primary Energy', 'Primary energy includes electricity, transport, and heating; values use the substitution method.');
  addImageContain(slide, 'figure_2.jpg', 0.45, 1.12, 6.2, 3.62);
  statCard(slide, '~14%', 'of global primary energy is renewable', 6.95, 1.18, 2.35, 1.22, theme.green, 'Approximately one-seventh of all energy.');
  bulletList(slide, [
    'Lower than the electricity share because transport and heating remain oil- and gas-heavy.',
    'High-renewable primary-energy systems include Norway, Brazil, and New Zealand.',
    'Several fossil-fuel-producing countries in the Middle East and parts of Asia remain below 5%.'
  ], 6.95, 2.75, 2.45, 1.45, 8.1);
  pill(slide, 'Primary energy ≠ electricity only', 7.02, 4.35, 2.15, theme.green, 'E8F5EE');
  addSource(slide, 'Source: Our World in Data – share of primary energy from renewables by country, 2024.');
}

// 4 Renewable generation breakdown
{
  const slide = slideBase();
  addTitle(slide, 'Renewable Electricity Generation Is Growing Rapidly, Led by Wind and Solar', 'Hydropower still leads, but wind and solar combined now nearly match its output.');
  const gen = [
    { label: 'Hydro', value: 4500, color: theme.blue, share: '~47%' },
    { label: 'Wind', value: 2400, color: theme.green, share: '~25%' },
    { label: 'Solar', value: 2000, color: theme.gold, share: '~21%' },
    { label: 'Other', value: 700, color: '9A7BB7', share: '~7%' },
  ];
  addColumnChart(slide, gen, 0.68, 1.34, 5.55, 2.9, 4800, 'Approx. global generation, 2024 (TWh)');
  slide.addShape(pptx.ShapeType.roundRect, { x: 6.68, y: 1.15, w: 2.7, h: 3.68, rectRadius: 0.08, fill: { color: theme.panel }, line: { color: theme.line, width: 0.8 } });
  slide.addText('Technology breakdown', { x: 6.92, y: 1.38, w: 2.2, h: 0.22, fontSize: 10.3, bold: true, color: theme.ink, margin: 0 });
  gen.forEach((d, i) => {
    const yy = 1.82 + i * 0.55;
    slide.addShape(pptx.ShapeType.rect, { x: 6.95, y: yy + 0.06, w: 0.12, h: 0.12, fill: { color: d.color }, line: { color: d.color, transparency: 100 } });
