  slide.addText('Since ~2010, wind and solar have accelerated most sharply, reshaping the renewable mix even while hydro remains the largest source.', { x: 6.95, y: 4.18, w: 2.16, h: 0.38, fontSize: 7.5, bold: true, color: theme.ink, margin: 0.01, fit: 'shrink' });
  addSource(slide, 'Source: Brief technology table; approximate global generation, 2024.');
}

// 5 Electricity one-third renewable
{
  const slide = slideBase();
  addTitle(slide, 'Almost One-Third of Global Electricity Now Comes from Renewables', 'Electricity is where renewables have made the most visible progress.');
